import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"EventLoop","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/event-loop.md","filePath":"zh/api/event-loop.md","lastUpdated":1786973110000}'),c={name:"zh/api/event-loop.md"};function r(l,e,i,h,n,p){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="eventloop" tabindex="-1">EventLoop <a class="header-anchor" href="#eventloop" aria-label="Permalink to &quot;EventLoop&quot;">​</a></h1><p>CV 驱动的帧调度器、协程调度器和定时器队列。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>EventLoop</code> 管理应用主循环，以目标帧率运行。支持通过 <code>Schedule()</code> 调度 C++20 协程，通过 <code>ScheduleYield()</code> 实现单帧让出，通过 <code>ScheduleSleep()</code> 实现定时恢复。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>Run(frame_callback)</code></td><td>启动事件循环，阻塞直到 <code>Stop()</code></td></tr><tr><td><code>Stop()</code></td><td>停止事件循环</td></tr><tr><td><code>WakeUp()</code></td><td>从空闲等待中唤醒循环</td></tr><tr><td><code>Schedule(task)</code></td><td>调度一个 <code>Task&lt;void&gt;</code> 协程</td></tr><tr><td><code>ScheduleYield(handle)</code></td><td>下一帧恢复句柄（由 <code>Yield()</code> 使用）</td></tr><tr><td><code>ScheduleSleep(duration, handle)</code></td><td>指定时长后恢复句柄（由 <code>Sleep()</code> 使用）</td></tr><tr><td><code>SetTargetFps(fps)</code></td><td>设置目标帧率</td></tr><tr><td><code>GetTargetFps() -&gt; int</code></td><td>获取目标帧率</td></tr><tr><td><code>GetFrameCount() -&gt; uint64_t</code></td><td>获取已处理帧数</td></tr></tbody></table><h2 id="协程生命周期" tabindex="-1">协程生命周期 <a class="header-anchor" href="#协程生命周期" aria-label="Permalink to &quot;协程生命周期&quot;">​</a></h2><p>循环对所有调度的协程使用 <code>shared_ptr&lt;Task&lt;void&gt;&gt;</code>。<code>active_tasks_</code> map（以句柄地址为 key）持有共享所有权，确保只要定时器或 yield 等待中的句柄还引用着协程，协程帧就不会被销毁。详见 <a href="./../guide/coroutines">协程</a>。</p><h2 id="线程安全" tabindex="-1">线程安全 <a class="header-anchor" href="#线程安全" aria-label="Permalink to &quot;线程安全&quot;">​</a></h2><p><code>Schedule()</code>、<code>ScheduleYield()</code> 和 <code>ScheduleSleep()</code> 由互斥锁保护，可从任意线程调用。<code>WakeUp()</code> 线程安全。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./task">Task</a></li><li><a href="./application">Application</a></li><li><a href="./../guide/coroutines">协程指南</a></li></ul>',12)])])}const _=t(c,[["render",r]]);export{u as __pageData,_ as default};
